// Monta o link de indicação do usuário
// Ex: https://logrotas.vercel.app?ref=11987354715
const montarLinkIndicacao=(whatsappOuId)=>{
  const id=String(whatsappOuId).replace(/\D/g,"")||"usuario";
  return `${BASE_URL}?ref=${id}`;
};

